create extension if not exists pgcrypto;
create table organisation(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table directory_user(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,username text not null,email text not null,display_name text not null,attributes jsonb not null default '{}'::jsonb,active boolean not null default true,unique(organisation_id,username),unique(organisation_id,email));
create table directory_group(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,dynamic_rule jsonb,unique(organisation_id,name));
create table client_application(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,protocol text not null check(protocol in('oidc','saml','oauth')),client_id text not null,redirect_uris text[] not null default '{}',owner text,active boolean not null default false,created_at timestamptz not null default now(),unique(organisation_id,client_id));
create table access_policy(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,version integer not null,rules jsonb not null,mode text not null check(mode in('dry_run','enforced','retired')),created_at timestamptz not null default now(),unique(organisation_id,name,version));
create table auth_session(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,user_id uuid not null references directory_user(id),application_id uuid references client_application(id),assurance text not null,device_id text,risk_score integer not null check(risk_score between 0 and 100),started_at timestamptz not null default now(),expires_at timestamptz not null,terminated_at timestamptz);
create table authentication_event(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,user_id uuid references directory_user(id),application_id uuid references client_application(id),event_type text not null,decision text not null check(decision in('allow','step_up','block')),risk_score integer not null check(risk_score between 0 and 100),context jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create index authentication_event_org_time_idx on authentication_event(organisation_id,occurred_at desc);
create table signing_key(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,key_id text not null,kms_uri text not null,algorithm text not null,state text not null check(state in('prepublished','active','retiring','retired')),created_at timestamptz not null default now(),unique(organisation_id,key_id));
create table audit_event(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,actor_id text not null,action text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create table role_policy(organisation_id uuid not null references organisation(id) on delete cascade,role_key text not null,permissions text[] not null default '{}',updated_by text not null,updated_at timestamptz not null default now(),primary key(organisation_id,role_key));
